import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const primeiro=v=>Array.isArray(v)?v[0]:v;
export function converterLibraryCongress(item){
 const id=String(item?.id||item?.url||'').trim();if(!id)return null;const ler=endereco(item.url)||endereco(item.id);if(!ler)return null;
 const autores=[...(Array.isArray(item.contributor)?item.contributor:[]),...(Array.isArray(item.creator)?item.creator:[item.creator].filter(Boolean))].map(String),langs=idiomas(Array.isArray(item.language)?item.language:[item.language].filter(Boolean)),capa=endereco(Array.isArray(item.image_url)?item.image_url.at(-1):item.image_url)||null;
 const online=Array.isArray(item.online_format)?item.online_format:[],digital=online.length>0||Array.isArray(item.resources)&&item.resources.length>0;if(!digital)return null;
 return{id:`loc:${id}`,fonte:'loc',provedor:'Library of Congress',titulo:String(item.title||'Sem título'),autores:[...new Set(autores)],idiomas:langs,capa,descricao:String(primeiro(item.description)||primeiro(item.notes)||''),acessoLivre:true,dominioPublico:false,tipoAcesso:'Item digital gratuito',licenca:'Item digital acessível gratuitamente na Library of Congress. Direitos de cópia e reutilização variam por item e são informados na fonte.',origem:ler,ler,texto:null,formatos:[]};
}
export async function pesquisarLibraryCongress(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','loc');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,13000,2),itens=Array.isArray(d.results)?d.results:[],total=Number(d?.pagination?.total)||itens.length,livros=itens.map(converterLibraryCongress).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));return{livros,total,temMais:Boolean(d?.pagination?.next)||pagina*20<total}}
